extends Sprite2D

# Coordinate di riferimento e raggio di raccolta
const START_Y: float = 80.0
const SPAWN_MIN_X: float = 64.0
const SPAWN_MAX_X: float = 1088.0
const RESET_Y: float = 680.0
const CATCH_DISTANCE: float = 60.0

# Tabella dei tipi di oggetto configurati come dati
const ITEM_TYPES: Dictionary = {
	"star": {
		"points": 10,
		"speed": 180.0,
		"color": Color.YELLOW
	},
	"gold_star": {
		"points": 50,
		"speed": 260.0,
		"color": Color.ORANGE
	},
	"rock": {
		"points": -20,
		"speed": 220.0,
		"color": Color.GRAY
	}
}

# Variabili di stato dell'oggetto che cade
var star_name: String = "star"
var fall_speed: float = 180.0
var points: int = 10
var is_collected: bool = false


func _ready() -> void:
	# Mantiene la posizione definita prima di add_child se gia' impostata
	var initial_pos: Vector2 = position
	reset_star()
	if initial_pos != Vector2.ZERO:
		position = initial_pos


func _process(delta: float) -> void:
	# L'oggetto scende solo se non e' ancora stato raccolto
	if not is_collected:
		position.y += fall_speed * delta


func reset_star() -> void:
	# Assegna una coordinata orizzontale casuale e riposiziona in alto
	var random_x: float = randf_range(SPAWN_MIN_X, SPAWN_MAX_X)
	position = Vector2(random_x, START_Y)
	is_collected = false

	# Sceglie a caso uno dei tre tipi dall'Array di nomi e ne applica i dati
	var types: Array[String] = ["star", "gold_star", "rock"]
	var random_index: int = randi_range(0, types.size() - 1)
	var chosen_type: String = types[random_index]
	apply_item_type(chosen_type)


func apply_item_type(type_name: String) -> void:
	# Verifica che la chiave esista prima di accedere ai suoi dati
	if type_name in ITEM_TYPES:
		var config: Dictionary = ITEM_TYPES[type_name]
		star_name = type_name
		points = config["points"]
		fall_speed = config["speed"]
		modulate = config["color"]


func is_caught(basket_position: Vector2) -> bool:
	# Misura la distanza in pixel dal cesto e verifica se rientra nella soglia
	var distance: float = position.distance_to(basket_position)
	return distance < CATCH_DISTANCE

extends Sprite2D

# Posizione di partenza fissa del cesto sullo schermo
const START_POSITION: Vector2 = Vector2(576, 600)

# Enumerazione degli stati del gioco
enum GameState { PLAYING, GAME_OVER, PAUSED, WIN }

# Variabili di stato del cesto
var current_state: GameState = GameState.PLAYING
var player_name: String = "Cesto"
var speed: float = 350.0
var lives: int = 3
var score: int = 0
var is_active: bool = true

# Variabili per contare il tempo e scandire la generazione periodica
var game_time: float = 0.0
var spawn_timer: float = 0.0

# Array delle stelle attive sullo schermo
var stars: Array[Sprite2D] = []

# Dizionario per memorizzare il numero di oggetti raccolti per ogni tipo
var collected_counts: Dictionary = {
	"star": 0,
	"gold_star": 0,
	"rock": 0
}


func _ready() -> void:
	position = START_POSITION
	modulate = Color.GREEN
	update_ui()
	spawn_initial_stars(5)
	spawn_rock_row()
	print("Cesto pronto: ", player_name, " in ", position)


func _process(delta: float) -> void:
	match current_state:
		GameState.PLAYING:
			if Input.is_action_just_pressed("ui_cancel"):
				current_state = GameState.PAUSED
				$Label.text = "Gioco in pausa. Premi Esc per riprendere"
			else:
				# Accumula il tempo totale e il timer di generazione periodica
				game_time += delta
				spawn_timer += delta

				# Genera una nuova stella ogni volta che il timer raggiunge l'intervallo
				var interval: float = get_spawn_interval()
				if spawn_timer >= interval:
					spawn_timer -= interval
					spawn_star()

				move_basket(delta)
				check_stars()
				check_win()
				check_game_over()
		GameState.GAME_OVER:
			check_restart()
		GameState.PAUSED:
			if Input.is_action_just_pressed("ui_cancel"):
				current_state = GameState.PLAYING
				update_ui()
		GameState.WIN:
			if Input.is_action_just_pressed("ui_accept"):
				reset_game()


func move_basket(delta: float) -> void:
	var direction: float = 0.0
	if Input.is_action_pressed("move_left"):
		direction -= 1.0
	if Input.is_action_pressed("move_right"):
		direction += 1.0

	position.x += direction * speed * delta
	position.x = clamp(position.x, 64.0, 1088.0)


func get_difficulty_factor() -> float:
	# Restituisce un valore da 0.0 a 1.0 nei primi 60 secondi
	return min(game_time / 60.0, 1.0)


func get_spawn_interval() -> float:
	# L'intervallo scende da 2.0 a 0.5 secondi e non puo' scendere oltre
	var interval: float = lerpf(2.0, 0.5, get_difficulty_factor())
	return max(interval, 0.5)


func spawn_star() -> void:
	var star_scene: PackedScene = load("res://star.tscn")
	var new_star: Sprite2D = star_scene.instantiate() as Sprite2D

	# Calcola un aumento di velocita' in base alla difficolta' corrente
	var speed_boost: float = lerpf(0.0, 150.0, get_difficulty_factor())
	new_star.fall_speed += speed_boost

	add_child(new_star)
	stars.append(new_star)


func spawn_initial_stars(count: int) -> void:
	for i in range(count):
		spawn_star()


func check_stars() -> void:
	for i in range(stars.size() - 1, -1, -1):
		var current_star: Sprite2D = stars[i]
		if current_star.is_caught(position):
			if current_star.points >= 0:
				add_score(current_star.points)
			else:
				take_damage(1)

			if current_star.star_name in collected_counts:
				collected_counts[current_star.star_name] += 1

			remove_child(current_star)
			stars.remove_at(i)
			spawn_star()
		elif current_star.position.y > 680.0:
			remove_child(current_star)
			stars.remove_at(i)
			spawn_star()


func get_collected_count(type_name: String) -> int:
	return collected_counts.get(type_name, 0)


func boost_all_stars(extra_speed: float) -> void:
	for star in stars:
		star.fall_speed += extra_speed


func spawn_rock_row() -> void:
	var rock_scene: PackedScene = load("res://rock.tscn")
	var current_x: float = 160.0
	while current_x <= 960.0:
		var rock: Sprite2D = rock_scene.instantiate() as Sprite2D
		rock.position = Vector2(current_x, 200.0)
		add_child(rock)
		current_x += 200.0


func update_ui() -> void:
	$Label.text = "Punti: %04d | Vite: %d" % [score, lives]


func set_speed(new_speed: float) -> void:
	speed = new_speed


func add_score(amount: int) -> void:
	score += amount
	boost_all_stars(10.0)
	update_ui()


func take_damage(amount: int) -> void:
	lives -= amount
	if lives <= 0:
		lives = 0
		is_active = false
	update_ui()


func check_win() -> void:
	if score >= 100:
		current_state = GameState.WIN
		$Label.text = "Vittoria! Punti: %d | Premi Invio per giocare ancora" % score


func check_game_over() -> void:
	if lives <= 0:
		current_state = GameState.GAME_OVER
		$Label.text = "Partita finita! Premi Invio per ricominciare"


func check_restart() -> void:
	if Input.is_action_just_pressed("ui_accept"):
		reset_game()


func reset_game() -> void:
	lives = 3
	score = 0
	game_time = 0.0
	spawn_timer = 0.0
	position = START_POSITION
	current_state = GameState.PLAYING
	is_active = true
	update_ui()
